// USR Driver – converts sequence items to pin-level stimulus via clocking block
class usr_driver extends uvm_driver #(usr_seq_item);
  `uvm_component_utils(usr_driver)

  virtual usr_if vif;

  function new(string name = "usr_driver", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    if (!uvm_config_db#(virtual usr_if)::get(this, "", "vif", vif))
      `uvm_fatal("DRV", "Failed to get virtual interface from config_db")
  endfunction

  virtual task run_phase(uvm_phase phase);
    usr_seq_item item;

    // Initialize all outputs to known values
    vif.cb.clr             <= 1'b1;
    vif.cb.control         <= 2'b00;
    vif.cb.parallel_in     <= 8'h00;
    vif.cb.serial_in_right <= 1'b0;
    vif.cb.serial_in_left  <= 1'b0;
    @(vif.cb); // Wait one cycle for init

    forever begin
      seq_item_port.get_next_item(item);

      // Drive signals using the clocking block
      vif.cb.clr             <= item.clr;
      vif.cb.control         <= item.control;
      vif.cb.parallel_in     <= item.parallel_in;
      vif.cb.serial_in_right <= item.serial_in_right;
      vif.cb.serial_in_left  <= item.serial_in_left;

      @(vif.cb); // Wait for the clock edge to latch values

      seq_item_port.item_done();
    end
  endtask
endclass

