// USR Monitor – samples DUT signals independently and broadcasts transactions
class usr_monitor extends uvm_monitor;
  `uvm_component_utils(usr_monitor)

  virtual usr_if vif;
  uvm_analysis_port #(usr_seq_item) ap;

  function new(string name = "usr_monitor", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    ap = new("ap", this);
    if (!uvm_config_db#(virtual usr_if)::get(this, "", "vif", vif))
      `uvm_fatal("MON", "Failed to get virtual interface from config_db")
  endfunction

  virtual task run_phase(uvm_phase phase);
    usr_seq_item txn;

    // Wait for initial clock edge
   @(vif.cb_mon);

forever begin
  @(vif.cb_mon);

  txn = usr_seq_item::type_id::create("txn");

  txn.clr              = vif.cb_mon.clr;
  txn.control          = vif.cb_mon.control;
  txn.parallel_in      = vif.cb_mon.parallel_in;
  txn.serial_in_right  = vif.cb_mon.serial_in_right;
  txn.serial_in_left   = vif.cb_mon.serial_in_left;

  txn.serial_out_right = vif.cb_mon.serial_out_right;
  txn.serial_out_left  = vif.cb_mon.serial_out_left;
  txn.parallel_out     = vif.cb_mon.parallel_out;

  ap.write(txn);
end
  endtask
endclass

