// ════════════════════════════════════════════════════════════

class usr_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(usr_scoreboard)

  uvm_analysis_imp #(usr_seq_item, usr_scoreboard) analysis_imp;

  // Reference model state — represents what parallel_out SHOULD be
  // at the moment we sample it (i.e., the result of the PREVIOUS cycle's stimulus)
  logic [7:0]  ref_parallel_out;
  bit          ref_valid;        // false until we've seen one txn (initial X is unknown)
  int unsigned txn_count;
  int unsigned pass_count;
  int unsigned fail_count;

  function new(string name = "usr_scoreboard", uvm_component parent = null);
    super.new(name, parent);
    ref_parallel_out = 8'hxx;
    ref_valid        = 1'b0;
    txn_count        = 0;
    pass_count       = 0;
    fail_count       = 0;
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    analysis_imp = new("analysis_imp", this);
  endfunction

  // The monitor samples the input pins and the registered output on the SAME edge.
  // Because parallel_out is registered, on edge N it reflects the stimulus driven
  // at edge N-1. So we:
  //   1. Compare txn.parallel_out against ref_parallel_out (the prediction made
  //      from the PREVIOUS transaction's stimulus).
  //   2. Use THIS transaction's stimulus to compute what parallel_out should be
  //      next cycle, and store that as the new ref_parallel_out.
  virtual function void write(usr_seq_item txn);
    logic [7:0] expected_now;
    logic [7:0] next_ref;
    logic       expected_sor;
    logic       expected_sol;

    txn_count++;

    // -------- Step 1: Check current outputs against previous prediction --------
    expected_now = ref_parallel_out;
    expected_sor = expected_now[0];
    expected_sol = expected_now[7];

    if (ref_valid) begin
      if (txn.parallel_out !== expected_now) begin
        `uvm_error("SB", $sformatf(
          "MISMATCH [txn#%0d]: clr=%0b ctrl=%0b par_in=0x%02h | Expected par_out=0x%02h, Got=0x%02h",
          txn_count, txn.clr, txn.control, txn.parallel_in,
          expected_now, txn.parallel_out))
        fail_count++;
      end else begin
        pass_count++;
      end

      if (txn.serial_out_right !== expected_sor) begin
        `uvm_error("SB", $sformatf(
          "MISMATCH serial_out_right [txn#%0d]: Expected=%0b, Got=%0b",
          txn_count, expected_sor, txn.serial_out_right))
      end

      if (txn.serial_out_left !== expected_sol) begin
        `uvm_error("SB", $sformatf(
          "MISMATCH serial_out_left [txn#%0d]: Expected=%0b, Got=%0b",
          txn_count, expected_sol, txn.serial_out_left))
      end
    end
    else begin
      // First sample after construction — output is undefined until the first
      // clocked update propagates. Skip the compare but still count the txn.
      `uvm_info("SB", $sformatf(
        "Skipping check on txn#%0d (initial sample, no prior prediction)",
        txn_count), UVM_HIGH)
    end

    // -------- Step 2: Predict next cycle's parallel_out from THIS stimulus --------
    if (txn.clr) begin
      next_ref = 8'h00;
    end
    else begin
      case (txn.control)
        2'b00:   next_ref = ref_valid ? ref_parallel_out : 8'hxx;     // Hold
        2'b01:   next_ref = ref_valid                                  // Right shift
                            ? {txn.serial_in_left, ref_parallel_out[7:1]}
                            : 8'hxx;
        2'b10:   next_ref = ref_valid                                  // Left shift
                            ? {ref_parallel_out[6:0], txn.serial_in_right}
                            : 8'hxx;
        2'b11:   next_ref = txn.parallel_in;                           // Parallel load
        default: next_ref = ref_valid ? ref_parallel_out : 8'hxx;
      endcase
    end

    ref_parallel_out = next_ref;
    // Once we drive a known value (clear or parallel load), predictions become
    // valid. Hold/shift before any known load would still be X, so only flip
    // ref_valid when we actually know the state.
    if (txn.clr || txn.control == 2'b11)
      ref_valid = 1'b1;
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("SB", $sformatf(
      "Scoreboard Summary: Total=%0d, Pass=%0d, Fail=%0d",
      txn_count, pass_count, fail_count), UVM_LOW)
    if (fail_count > 0)
      `uvm_error("SB", $sformatf("%0d transactions FAILED", fail_count))
    else
      `uvm_info("SB", "All transactions PASSED", UVM_LOW)
  endfunction
endclass

