// USR Functional Coverage Subscriber
class usr_coverage extends uvm_subscriber #(usr_seq_item);
  `uvm_component_utils(usr_coverage)

  usr_seq_item txn;

  // Covergroup definition
  covergroup usr_cg;

    // Clear signal
    cp_clr: coverpoint txn.clr {
      bins asserted   = {1};
      bins deasserted = {0};
    }

    // Control modes
    cp_control: coverpoint txn.control {
      bins hold          = {2'b00};
      bins right_shift   = {2'b01};
      bins left_shift    = {2'b10};
      bins parallel_load = {2'b11};
    }

    // Parallel input corner cases
    cp_parallel_in: coverpoint txn.parallel_in {
      bins zero    = {8'h00};
      bins max     = {8'hFF};
      bins alt_lo  = {8'h55};
      bins alt_hi  = {8'hAA};
      bins low     = {[8'h01:8'h3F]};
      bins mid     = {[8'h40:8'hBF]};
      bins high    = {[8'hC0:8'hFE]};
    }

    // Serial inputs
    cp_serial_in_right: coverpoint txn.serial_in_right {
      bins val[] = {0, 1};
    }

    cp_serial_in_left: coverpoint txn.serial_in_left {
      bins val[] = {0, 1};
    }

    // Serial outputs
    cp_serial_out_right: coverpoint txn.serial_out_right {
      bins val[] = {0, 1};
    }

    cp_serial_out_left: coverpoint txn.serial_out_left {
      bins val[] = {0, 1};
    }

    // Parallel output corner cases
    cp_parallel_out: coverpoint txn.parallel_out {
      bins zero    = {8'h00};
      bins max     = {8'hFF};
      bins low     = {[8'h01:8'h7F]};
      bins high    = {[8'h80:8'hFE]};
    }

    // Cross coverage: control mode x clear
    cx_control_clr: cross cp_control, cp_clr;

    // Cross coverage: control mode x serial_in_right (relevant for left shift)
    cx_control_sir: cross cp_control, cp_serial_in_right {
      // Most interesting when control == left_shift
      ignore_bins irrelevant_hold  = binsof(cp_control.hold);
      ignore_bins irrelevant_rsh   = binsof(cp_control.right_shift);
      ignore_bins irrelevant_pload = binsof(cp_control.parallel_load);
    }

    // Cross coverage: control mode x serial_in_left (relevant for right shift)
    cx_control_sil: cross cp_control, cp_serial_in_left {
      ignore_bins irrelevant_hold  = binsof(cp_control.hold);
      ignore_bins irrelevant_lsh   = binsof(cp_control.left_shift);
      ignore_bins irrelevant_pload = binsof(cp_control.parallel_load);
    }

    // Cross coverage: parallel load x parallel_in values
    cx_pload_pin: cross cp_control, cp_parallel_in {
      ignore_bins not_load_hold = binsof(cp_control.hold);
      ignore_bins not_load_rsh  = binsof(cp_control.right_shift);
      ignore_bins not_load_lsh  = binsof(cp_control.left_shift);
    }

  endgroup

  // Transition covergroup for control mode sequences
  covergroup usr_transition_cg;
    cp_ctrl_trans: coverpoint txn.control {
      bins hold_to_hold         = (2'b00 => 2'b00);
      bins hold_to_rshift       = (2'b00 => 2'b01);
      bins hold_to_lshift       = (2'b00 => 2'b10);
      bins hold_to_pload        = (2'b00 => 2'b11);
      bins rshift_to_hold       = (2'b01 => 2'b00);
      bins lshift_to_hold       = (2'b10 => 2'b00);
      bins pload_to_hold        = (2'b11 => 2'b00);
      bins pload_to_rshift      = (2'b11 => 2'b01);
      bins pload_to_lshift      = (2'b11 => 2'b10);
      bins rshift_to_lshift     = (2'b01 => 2'b10);
      bins lshift_to_rshift     = (2'b10 => 2'b01);
      bins pload_to_pload       = (2'b11 => 2'b11);
    }
  endgroup

  function new(string name = "usr_coverage", uvm_component parent = null);
    super.new(name, parent);
    usr_cg = new();
    usr_transition_cg = new();
  endfunction

  virtual function void write(usr_seq_item t);
    txn = t;
    usr_cg.sample();
    usr_transition_cg.sample();
  endfunction

  function void report_phase(uvm_phase phase);
    super.report_phase(phase);
    `uvm_info("COV", $sformatf("Functional Coverage: %.2f%%", usr_cg.get_coverage()), UVM_LOW)
    `uvm_info("COV", $sformatf("Transition Coverage: %.2f%%", usr_transition_cg.get_coverage()), UVM_LOW)
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Agent (uvm_agent)
// ════════════════════════════════════════════════════════════

// USR Agent – bundles driver, sequencer, and monitor
class usr_agent extends uvm_agent;
  `uvm_component_utils(usr_agent)

  usr_driver    drv;
  usr_sequencer sqr;
  usr_monitor   mon;

  function new(string name = "usr_agent", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);

    // Monitor is always instantiated (active or passive)
    mon = usr_monitor::type_id::create("mon", this);

    if (get_is_active() == UVM_ACTIVE) begin
      drv = usr_driver::type_id::create("drv", this);
      sqr = usr_sequencer::type_id::create("sqr", this);
    end
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    if (get_is_active() == UVM_ACTIVE) begin
      drv.seq_item_port.connect(sqr.seq_item_export);
    end
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Environment (uvm_env)
// ════════════════════════════════════════════════════════════

// USR Environment – instantiates agent, scoreboard, and coverage collector
class usr_env extends uvm_env;
  `uvm_component_utils(usr_env)

  usr_agent      agent;
  usr_scoreboard sb;
  usr_coverage   cov;

  function new(string name = "usr_env", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    agent = usr_agent::type_id::create("agent", this);
    sb    = usr_scoreboard::type_id::create("sb", this);
    cov   = usr_coverage::type_id::create("cov", this);
  endfunction

  function void connect_phase(uvm_phase phase);
    super.connect_phase(phase);
    // Connect monitor analysis port to scoreboard and coverage
    agent.mon.ap.connect(sb.analysis_imp);
    agent.mon.ap.connect(cov.analysis_export);
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// Test (uvm_test)
// ════════════════════════════════════════════════════════════

// USR Base Test – configures environment and starts master sequence
class usr_base_test extends uvm_test;
  `uvm_component_utils(usr_base_test)

  usr_env env;

  function new(string name = "usr_base_test", uvm_component parent = null);
    super.new(name, parent);
  endfunction

  function void build_phase(uvm_phase phase);
    super.build_phase(phase);
    env = usr_env::type_id::create("env", this);
  endfunction

  virtual task run_phase(uvm_phase phase);
    usr_master_seq master_seq;

    phase.raise_objection(this, "Starting USR test");

    master_seq = usr_master_seq::type_id::create("master_seq");
    master_seq.start(env.agent.sqr);

    // Allow some drain time for final checks
    #100;

    phase.drop_objection(this, "USR test complete");
  endtask

  function void report_phase(uvm_phase phase);
    uvm_report_server svr;
    super.report_phase(phase);
    svr = uvm_report_server::get_server();
    if (svr.get_severity_count(UVM_ERROR) == 0 &&
        svr.get_severity_count(UVM_FATAL) == 0)
      `uvm_info("TEST", "===== TEST PASSED =====", UVM_NONE)
    else
      `uvm_info("TEST", "===== TEST FAILED =====", UVM_NONE)
  endfunction
endclass

// ════════════════════════════════════════════════════════════
// UVM Top (tb_top)
// ════════════════════════════════════════════════════════════

// TB Top – instantiates DUT, interface, generates clock, and calls run_test()

module tb_top;

  // Clock generation
  logic clk;
  initial begin
    clk = 0;
    forever #5 clk = ~clk; // 100 MHz clock (10ns period)
  end

  // Instantiate the interface
  usr_if intf(.clk(clk));

  // Instantiate the DUT and connect to interface signals
  universal_shift_register dut (
    .clk              (clk),
    .clr              (intf.clr),
    .control          (intf.control),
    .parallel_in      (intf.parallel_in),
    .serial_in_right  (intf.serial_in_right),
    .serial_in_left   (intf.serial_in_left),
    .serial_out_right (intf.serial_out_right),
    .serial_out_left  (intf.serial_out_left),
    .parallel_out     (intf.parallel_out)
  );

  // Store virtual interface in config_db for UVM components
  initial begin
    uvm_config_db#(virtual usr_if)::set(null, "*", "vif", intf);
  end

  // Start UVM test
  initial begin
    run_test("usr_base_test");
  end

  // Simulation timeout safety net
  initial begin
    #100_000;
    `uvm_fatal("TB_TOP", "Simulation timeout reached!")
  end

  // Optional: waveform dump for debug
  initial begin
    $dumpfile("usr_waves.vcd");
    $dumpvars(0, tb_top);
  end

endmodule

